#!/usr/bin/env bash
# SWE-Odyssey step setup (generated by `odyssey compile`; see docs/SPEC.md section 4).
#
# Harbor uploads this step's workdir/ into the container's cwd (the repo root)
# and runs `bash <cwd>/setup.sh` before the agent starts. This script stops
# whatever the previous agent left running, puts the working tree into the
# state the arm's code-state policy prescribes, keeps the agent's memory, hides
# grading material, and then deletes itself and its payload so nothing about
# the experiment is left in the repo.
#
# Nothing the agent can write is trusted here: git never reads the agent's git
# config, and the base snapshot is checked against the hash manifest compiled
# into the payload before it is used.
set -euo pipefail

# --- compile-time values -----------------------------------------------------
@@CONFIG@@

# --- container layout (overridable only so the script can be tested on a host) -
: "${ODYSSEY_BASE_TARBALL:=/opt/odyssey/base.tar.gz}"
: "${ODYSSEY_TESTS_DIR:=/tests}"
: "${ODYSSEY_SOLUTION_DIR:=/solution}"
: "${ODYSSEY_VERIFIER_DIR:=/logs/verifier}"
: "${ODYSSEY_SCRATCH_ROOT:=/tmp}"
: "${ODYSSEY_STOP_AGENTS:=1}"
# Host tests only: restrict the process sweep to command lines containing this.
: "${ODYSSEY_SWEEP_MATCH:=}"

SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SELF="$SELF_DIR/$(basename "${BASH_SOURCE[0]}")"
PAYLOAD_SRC="$SELF_DIR/.odyssey_step"
PAYLOAD=""
MEMORY_SAVE=""

# A fixed, neutral identity and date: the snapshot commit depends only on the
# tree and says nothing about the experiment.
export GIT_AUTHOR_NAME=Maintainers GIT_AUTHOR_EMAIL=maintainers@localhost
export GIT_COMMITTER_NAME=Maintainers GIT_COMMITTER_EMAIL=maintainers@localhost
export GIT_AUTHOR_DATE='2024-01-01T00:00:00+0000' GIT_COMMITTER_DATE='2024-01-01T00:00:00+0000'
# The agent can write ~/.gitconfig, /etc/gitconfig and .git/config; a
# core.fsmonitor or hook there would run inside this script. Read none of them.
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null

log() { printf '[odyssey setup %s] %s\n' "$ODYSSEY_STEP" "$*" >&2; }
die() { log "ERROR: $*"; exit 1; }

git_() {
    git -c safe.directory='*' -c core.hooksPath=/dev/null -c core.fsmonitor=false \
        -c commit.gpgsign=false "$@"
}

cleanup() {
    if [ -n "$PAYLOAD" ]; then rm -rf "$PAYLOAD"; fi
    if [ -n "$MEMORY_SAVE" ]; then rm -rf "$MEMORY_SAVE"; fi
}
trap cleanup EXIT

# Move the payload out of the repo first, so it never ends up in a snapshot
# and is gone even if a later step fails.
take_payload() {
    PAYLOAD="$(mktemp -d "$ODYSSEY_SCRATCH_ROOT/odyssey-payload.XXXXXX")"
    if [ -d "$PAYLOAD_SRC" ]; then
        cp -a "$PAYLOAD_SRC/." "$PAYLOAD/"
        rm -rf "$PAYLOAD_SRC"
    fi
    rm -f "$SELF"
}

# --- process sweep: whatever the previous agent left running (templates/lib_sweep.sh)
@@INCLUDE lib_sweep.sh@@

# --- tree -----------------------------------------------------------------------

# Harbor never removes /tests after a step's verification, and the oracle's
# /solution would otherwise also linger into the next segment.
scrub_grading_material() {
    local dir
    for dir in "$ODYSSEY_TESTS_DIR" "$ODYSSEY_SOLUTION_DIR" "$ODYSSEY_VERIFIER_DIR"; do
        if [ -d "$dir" ]; then find "$dir" -mindepth 1 -maxdepth 1 -exec rm -rf {} + ; fi
    done
    rm -rf "$ODYSSEY_SCRATCH_ROOT"/odyssey-grade-*
}

save_memory_files() {
    MEMORY_SAVE="$(mktemp -d "$ODYSSEY_SCRATCH_ROOT/odyssey-memory.XXXXXX")"
    local f
    while IFS= read -r f; do
        [ -n "$f" ] || continue
        if [ -e "$ODYSSEY_WORKDIR/$f" ] || [ -L "$ODYSSEY_WORKDIR/$f" ]; then
            mkdir -p "$(dirname "$MEMORY_SAVE/$f")"
            cp -a "$ODYSSEY_WORKDIR/$f" "$MEMORY_SAVE/$f"
        fi
    done <<EOF
$ODYSSEY_MEMORY_FILES
EOF
}

restore_memory_files() {
    local f
    while IFS= read -r f; do
        [ -n "$f" ] || continue
        if [ -e "$MEMORY_SAVE/$f" ] || [ -L "$MEMORY_SAVE/$f" ]; then
            rm -rf "${ODYSSEY_WORKDIR:?}/$f"
            mkdir -p "$(dirname "$ODYSSEY_WORKDIR/$f")"
            cp -a "$MEMORY_SAVE/$f" "$ODYSSEY_WORKDIR/$f"
        fi
    done <<EOF
$ODYSSEY_MEMORY_FILES
EOF
}

# --- base snapshot manifest (templates/lib_manifest.sh) --------------------------
@@INCLUDE lib_manifest.sh@@

verify_base() {
    local manifest="$PAYLOAD/base.manifest"
    if [ ! -f "$manifest" ]; then
        log "no base manifest compiled in (sequence has no base_tree); base snapshot not verified"
        return 0
    fi
    tree_manifest "$ODYSSEY_WORKDIR" | cmp -s - "$manifest" \
        || die "base snapshot $ODYSSEY_BASE_TARBALL does not match the compiled manifest; refusing to start from a doctored tree"
}

rebuild_tree() {
    [ -f "$ODYSSEY_BASE_TARBALL" ] || die "base snapshot $ODYSSEY_BASE_TARBALL not found (image contract)"
    find "$ODYSSEY_WORKDIR" -mindepth 1 -maxdepth 1 -exec rm -rf {} +
    tar -xzf "$ODYSSEY_BASE_TARBALL" -C "$ODYSSEY_WORKDIR"
    verify_base
}

# A new repository with no history: no diff between segments, and none of the
# agent's git state (config, hooks, locks, half-finished rebases) survives.
fresh_repo() {
    rm -rf "${ODYSSEY_WORKDIR:?}/.git"
    (cd "$ODYSSEY_WORKDIR" && git_ -c init.defaultBranch=main init -q)
}

apply_state_patch() {
    local patch="$PAYLOAD/state.patch"
    [ -s "$patch" ] || return 0
    (cd "$ODYSSEY_WORKDIR" && git_ apply --check --whitespace=nowarn "$patch") \
        || die "state.patch does not apply to the base snapshot (tickets: $ODYSSEY_STATE_TICKETS)"
    (cd "$ODYSSEY_WORKDIR" && git_ apply --whitespace=nowarn "$patch")
}

commit_snapshot() {
    (
        cd "$ODYSSEY_WORKDIR"
        git_ add -A
        git_ commit -q --allow-empty --no-verify -m "Initial commit"
    )
}

seed_notes() {
    [ -f "$PAYLOAD/NOTES.md" ] || return 0
    cp "$PAYLOAD/NOTES.md" "$ODYSSEY_MEMORY_DIR/NOTES.md"
}

main() {
    [ -d "$ODYSSEY_WORKDIR" ] || die "workdir $ODYSSEY_WORKDIR does not exist"
    case "$ODYSSEY_WORKDIR" in /|/tmp|/var|/usr|/etc|/opt) die "refusing to reset system dir $ODYSSEY_WORKDIR";; esac
    if [ "$SELF_DIR" != "$ODYSSEY_WORKDIR" ]; then
        log "warning: setup.sh runs from $SELF_DIR, expected the workdir $ODYSSEY_WORKDIR"
    fi

    take_payload
    sweep_processes
    scrub_grading_material

    case "$ODYSSEY_CODE_STATE" in
        carry)
            # The files stay as the agent left them; only git is renewed.
            fresh_repo
            commit_snapshot
            ;;
        forward-merge|all-defects|single-defect)
            save_memory_files
            rebuild_tree
            fresh_repo
            apply_state_patch
            restore_memory_files
            commit_snapshot
            ;;
        *) die "unknown code-state policy $ODYSSEY_CODE_STATE" ;;
    esac

    mkdir -p "$ODYSSEY_MEMORY_DIR"
    seed_notes
    log "ready: policy $ODYSSEY_CODE_STATE"
}

main "$@"
